insert into public.products (id, slug, name, short, description, category, images, pack_size, variants, colors, features, featured, active, sort) values ('manija-rinon-ad', 'bolsa-manija-rinon-personalizada', 'Bolsa manija riñón personalizada', 'Alta densidad, impresa 1 cara 1 color. Pack de 100 unidades en 5 medidas.', 'La bolsa que lleva tu marca a cada lugar. Bolsas manija riñón de alta densidad, personalizadas con el logo, nombre o diseño de tu marca e impresas en serigrafía a 1 cara 1 color. Una presentación profesional para comercios, emprendimientos, tiendas online y marcas que quieren estar presentes en cada compra.', 'manija-rinon', '[{"src":"/img/productos/manija-rinon-20x30.webp","alt":"Bolsa manija riñón blanca 20 × 30 cm con la leyenda Tu logo aquí","color":"blanco"},{"src":"/img/productos/manija-rinon-25x35.webp","alt":"Bolsa manija riñón negra 25 × 35 cm con la leyenda Tu logo aquí","color":"negro"},{"src":"/img/productos/manija-rinon-30x40.webp","alt":"Bolsa manija riñón cristal 30 × 40 cm con la leyenda Tu logo aquí","color":"cristal"},{"src":"/img/productos/manija-rinon-35x45.webp","alt":"Bolsa manija riñón negra 35 × 45 cm con impresión naranja","color":"negro"},{"src":"/img/productos/manija-rinon-40x50.webp","alt":"Bolsa manija riñón lila 40 × 50 cm con la leyenda Tu logo aquí","color":"lila"}]'::jsonb, 100, '[{"size":"20 × 30 cm","price":44000,"image":"/img/productos/manija-rinon-20x30.webp"},{"size":"25 × 35 cm","price":47500,"image":"/img/productos/manija-rinon-25x35.webp"},{"size":"30 × 40 cm","price":52000,"image":"/img/productos/manija-rinon-30x40.webp"},{"size":"35 × 45 cm","price":57000,"image":"/img/productos/manija-rinon-35x45.webp"},{"size":"40 × 50 cm","price":67000,"image":"/img/productos/manija-rinon-40x50.webp"}]'::jsonb, array['blanco','negro','cristal','lila']::text[], array['Alta densidad','Impresión serigráfica 1 cara 1 color','4 colores de bolsa','Mínimo 100 unidades']::text[], true, true, 1) on conflict (id) do nothing;
insert into public.products (id, slug, name, short, description, category, images, pack_size, variants, colors, features, featured, active, sort) values ('hielo-pack-1500', 'pack-bolsas-para-hielo-personalizadas', 'Pack bolsas para hielo personalizadas ×1500', 'Tres medidas, tu marca en todas. 1.500 bolsas impresas a una cara y un color.', 'Un pack de 1.500 bolsas para hielo personalizadas, con impresión a una cara y un color: 500 de 26 × 40 cm (40 mic), 500 de 28 × 50 cm (50 mic) y 500 de 35 × 75 cm (60 mic). Material de baja densidad virgen, apto para contacto con alimentos. Ideal para fábricas de hielo, distribuidoras y almacenes.', 'hielo', '[{"src":"/img/clientes/thomas.webp","alt":"Bolsa transparente para hielo impresa para Thomas Hielo","color":"cristal"},{"src":"/img/promo-hielo.webp","alt":"Promoción de 1.500 bolsas para hielo personalizadas por 610.000 pesos"},{"src":"/img/clientes/thomas-grande.webp","alt":"Bolsa grande para hielo de Thomas Hielo, 8 y 10 kg","color":"cristal"}]'::jsonb, 1500, '[{"size":"Pack 3 medidas (26×40 · 28×50 · 35×75)","price":610000,"detail":"500 + 500 + 500 unidades"}]'::jsonb, array['cristal']::text[], array['Baja densidad virgen','Apto alimentos','3 medidas','1 cara 1 color']::text[], true, true, 2) on conflict (id) do nothing;
insert into public.products (id, slug, name, short, description, category, images, pack_size, variants, colors, features, featured, active, sort) values ('hielo-manija-rinon', 'bolsa-para-hielo-manija-rinon', 'Bolsa para hielo con manija riñón', 'Nuevo ingreso. 26 × 50 cm · 60 micrones. Para llevar el hielo con una mano.', 'Bolsa cristal para hielo con manija riñón, pensada para fábricas de hielo, distribuidoras, almacenes y estaciones de servicio. 26 × 50 cm en 60 micrones, resistente al peso y al frío, con tu marca bien visible en cada bolsa. Consultanos cantidades y precio.', 'hielo', '[{"src":"/img/bolsa-hielo.webp","alt":"Bolsa cristal para hielo con manija riñón y logo azul impreso","color":"cristal"},{"src":"/img/manija-rinon.webp","alt":"Detalle de la manija riñón de la bolsa para hielo"},{"src":"/img/tu-logo-aca.webp","alt":"Bolsa para hielo con la leyenda Tu logo acá impresa en azul","color":"cristal"}]'::jsonb, 1, '[{"size":"26 × 50 cm · 60 micrones","price":null}]'::jsonb, array['cristal']::text[], array['Manija riñón','60 micrones','Resistente al frío','Impresión personalizada']::text[], false, true, 3) on conflict (id) do nothing;
insert into public.products (id, slug, name, short, description, category, images, pack_size, variants, colors, features, featured, active, sort) values ('ecommerce', 'bolsas-para-ecommerce', 'Bolsas para ecommerce', 'Novedad. Rosa o negro, resistentes y seguras. Tu marca llega más lejos.', 'Dale a cada envío una presentación que se recuerde. Bolsas para ecommerce resistentes y seguras, ideales para envíos, disponibles en rosa y negro. Consultá medidas disponibles y la impresión de tu logo.', 'ecommerce', '[{"src":"/img/ecommerce-rosa.webp","alt":"Bolsa rosa para ecommerce impresa con la marca Visual Graf","color":"rosa"},{"src":"/img/promo-ecommerce.webp","alt":"Nuevas bolsas para ecommerce en rosa y negro"}]'::jsonb, 1, '[{"size":"Consultar medidas","price":null}]'::jsonb, array['rosa','negro']::text[], array['Resistentes y seguras','Ideales para envíos','Rosa o negro','Presentación profesional']::text[], true, true, 4) on conflict (id) do nothing;
insert into public.promotions (slug, title, description, badge, price, price_note, details, code, discount_percent, ends_at, image, cta, active) values ('pack-hielo-1500', 'Tres medidas. Tu marca en todas.', 'Un pack de 1.500 bolsas para hielo personalizadas, con impresión a una cara y un color.', 'Promoción destacada', 610000, 'Pack completo · 1.500 unidades en total', '[{"label":"26 × 40 cm","value":"500 u. · 40 mic"},{"label":"28 × 50 cm","value":"500 u. · 50 mic"},{"label":"35 × 75 cm","value":"500 u. · 60 mic"}]'::jsonb, null, null, null, '/img/promo-hielo.webp', '/productos/pack-bolsas-para-hielo-personalizadas', true) on conflict (slug) do nothing;
insert into public.promotions (slug, title, description, badge, price, price_note, details, code, discount_percent, ends_at, image, cta, active) values ('ecommerce', 'Tu marca llega más lejos', 'Novedad: bolsas para ecommerce en rosa y negro. Resistentes, seguras y con tu logo. Consultá medidas disponibles.', 'Novedad', null, null, null, null, null, null, '/img/promo-ecommerce.webp', '/productos/bolsas-para-ecommerce', true) on conflict (slug) do nothing;
